/**
 * Per-member project mutes. A mute only ever changes what its owner receives.
 */
import { and, asc, eq } from "drizzle-orm";
import { getDb, projectMutes } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId } from "./_mappers";
import type { OrgId, ProjectId, UserId } from "@/types/common";

export async function listMutedProjectIds(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ProjectId[]> {
  const rows = getDb()
    .select({ projectId: projectMutes.projectId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
      ),
    )
    .orderBy(asc(projectMutes.mutedAt), asc(projectMutes.projectId))
    .all();

  return rows.map((row) => brandId<ProjectId>(row.projectId));
}

/** Idempotent: muting an already muted project leaves the existing mute. */
export async function muteProject(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .insert(projectMutes)
    .values({
      orgId,
      userId,
      projectId,
      mutedAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing()
    .run();
}

/** Idempotent: unmuting a project that is not muted is a no-op. */
export async function unmuteProject(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .delete(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .run();
}
EOF

